function validate([nums1, nums2, nums3]) {
  for (const nums of [nums1, nums2, nums3]) {
    if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'Each array needs 1 to 100 values.';
    if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Every value is an integer from 1 to 100.';
  }
  return null;
}

