function twoOutOfThree(nums1, nums2, nums3) {
  const count = new Map();

  for (const nums of [nums1, nums2, nums3]) {
    const seen = new Set(nums);
    for (const value of seen) {
      count.set(value, (count.get(value) ?? 0) + 1);
    }
  }

  const result = [];
  for (const [value, arrays] of count) {
    if (arrays >= 2) {
      result.push(value);
    }
  }
  return result;
}

